import{_ as l,o as i,c as e,aw as t}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Алгоритм","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/blockchain/main/algoritm.md","filePath":"wiki/dev-commit/common2/blockchain/main/algoritm.md"}'),r={name:"wiki/dev-commit/common2/blockchain/main/algoritm.md"};function o(c,a,n,h,d,s){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h1><h2 id="⭐️-blockchain-server" tabindex="-1">⭐️ Blockchain Server <a class="header-anchor" href="#⭐️-blockchain-server" aria-label="Permalink to &quot;⭐️ Blockchain Server&quot;">​</a></h2><h4 id="_1-создать-blockchain-server" tabindex="-1">1. Создать Blockchain Server <a class="header-anchor" href="#_1-создать-blockchain-server" aria-label="Permalink to &quot;1. Создать Blockchain Server&quot;">​</a></h4><ul><li>На базе Ethereum и т.д.</li><li>IPFS</li><li>geth - Go приложение, позволяющее запустить свою Node Ethereum Blockchain локально или на удаленном сервере</li><li>Ganache - локальный блокчейн для разработки, который можно использовать для имитации поведения публичного блокчейна</li></ul><h4 id="_2-добавить-хранилище-для-blockchain-сети" tabindex="-1">2. Добавить хранилище для Blockchain-сети <a class="header-anchor" href="#_2-добавить-хранилище-для-blockchain-сети" aria-label="Permalink to &quot;2. Добавить хранилище для Blockchain-сети&quot;">​</a></h4><ul><li>Decentrilized Storages - хранилище</li><li>На базе Ethereum и т.д.</li><li>Pinata - базируется на IPFS</li><li>Filecoin - базируется на IPFS</li></ul><h4 id="_2-добавить-smart-contracts-к-blockchain" tabindex="-1">2. Добавить Smart Contracts к Blockchain <a class="header-anchor" href="#_2-добавить-smart-contracts-к-blockchain" aria-label="Permalink to &quot;2. Добавить Smart Contracts к Blockchain&quot;">​</a></h4><ul><li>Solidity</li><li>Remix - онлайн редактор кода для Smart Contracts. Позволяет добавлять Smart Contracts в Blockchain (production или тестовый)</li></ul><hr><h2 id="⭐️-crypto-wallet" tabindex="-1">⭐️ Crypto Wallet <a class="header-anchor" href="#⭐️-crypto-wallet" aria-label="Permalink to &quot;⭐️ Crypto Wallet&quot;">​</a></h2><h4 id="создать-крипто-кошелек" tabindex="-1">Создать крипто-кошелёк <a class="header-anchor" href="#создать-крипто-кошелек" aria-label="Permalink to &quot;Создать крипто-кошелёк&quot;">​</a></h4><ul><li>На базе Etherium Chain и т.д.</li><li>Metamask - сеть для передачи NFT</li></ul><hr><h2 id="⭐️-nft" tabindex="-1">⭐️ NFT <a class="header-anchor" href="#⭐️-nft" aria-label="Permalink to &quot;⭐️ NFT&quot;">​</a></h2><h4 id="создать-nft-для-фаила" tabindex="-1">Создать NFT для файла <a class="header-anchor" href="#создать-nft-для-фаила" aria-label="Permalink to &quot;Создать NFT для файла&quot;">​</a></h4><ul><li>NFT можно создавать через разные генераторы</li><li>Autominter</li></ul><hr><h2 id="⭐️-frontend-application-web-3-0" tabindex="-1">⭐️ Frontend Application Web 3.0 <a class="header-anchor" href="#⭐️-frontend-application-web-3-0" aria-label="Permalink to &quot;⭐️ Frontend Application Web 3.0&quot;">​</a></h2><h4 id="_1-добавить-авторизацию-через-wallet" tabindex="-1">1. Добавить авторизацию через Wallet <a class="header-anchor" href="#_1-добавить-авторизацию-через-wallet" aria-label="Permalink to &quot;1. Добавить авторизацию через Wallet&quot;">​</a></h4><ul><li>Добавить крипто-кошелек в приложение</li><li>Приложение через библиотеку Web3.js делает запрос к Wallet (кошельку) для авторизации пользователя</li><li>В кошельке хранится Etherium-аккаунт (например) пользователя для Blockchain</li><li>web3auth - инфраструктура для подключения кошельков</li></ul><h4 id="_2-реализовать-обращение-к-blockchain-server" tabindex="-1">2. Реализовать обращение к Blockchain Server <a class="header-anchor" href="#_2-реализовать-обращение-к-blockchain-server" aria-label="Permalink to &quot;2. Реализовать обращение к Blockchain Server&quot;">​</a></h4><ul><li>После авторизации, приложение может обращаться к Blockchain Server</li><li>Для обращения к Blockchain должна быть своя Node Blockchain - свой компьютер, подключенный к Blockchain сети и имеющей копию Etherium (например)</li></ul><p>Можно не создавать свою Node Blockchain, а воспользоваться API для доступа к Blockchain и облачным протоколам хранения:</p><ul><li>Infura</li><li>Moralis</li><li>Alchemy</li></ul><h4 id="_3-передать-nft-через-wallet" tabindex="-1">3. Передать NFT через Wallet <a class="header-anchor" href="#_3-передать-nft-через-wallet" aria-label="Permalink to &quot;3. Передать NFT через Wallet&quot;">​</a></h4><ul><li><ul><li></li></ul></li></ul>',26)])])}const k=l(r,[["render",o]]);export{m as __pageData,k as default};
